begin;


-- ============================================================
-- SSLCOMMERZ / PROVIDER PAYMENT IDENTIFIERS
-- ============================================================


-- ------------------------------------------------------------
-- Merchant transaction ID
--
-- This is generated by Emrinno and sent to SSLCOMMERZ
-- as `tran_id`.
--
-- SSLCOMMERZ currently allows max 30 characters.
-- ------------------------------------------------------------

alter table public.payments
  add column if not exists
    merchant_transaction_id text;


-- Backfill existing test rows if any.
update public.payments as p
set
  merchant_transaction_id =
    'EM'
    ||
    upper(
      substring(
        replace(
          p.id::text,
          '-',
          ''
        )
        from 1
        for 28
      )
    )
where
  p.merchant_transaction_id
    is null;


alter table public.payments
  alter column merchant_transaction_id
  set not null;


alter table public.payments
  add constraint
    payments_merchant_transaction_format_check
  check (
    char_length(
      merchant_transaction_id
    )
    between 3 and 30

    and merchant_transaction_id
      ~ '^[A-Z0-9_-]+$'
  );


create unique index
  if not exists
    payments_merchant_transaction_idx
on public.payments (
  merchant_transaction_id
);


-- ------------------------------------------------------------
-- Provider checkout/session reference.
--
-- For SSLCOMMERZ this stores the session key returned after
-- successful checkout-session creation.
-- ------------------------------------------------------------

alter table public.payments
  add column if not exists
    provider_session_id text;


create unique index
  if not exists
    payments_provider_session_idx
on public.payments (
  provider,
  provider_session_id
)
where
  provider_session_id
    is not null;


-- ------------------------------------------------------------
-- Validation ID.
--
-- SSLCOMMERZ supplies `val_id` after successful payment.
-- We later use this with the Order Validation API.
-- ------------------------------------------------------------

alter table public.payments
  add column if not exists
    provider_validation_id text;


create unique index
  if not exists
    payments_provider_validation_idx
on public.payments (
  provider,
  provider_validation_id
)
where
  provider_validation_id
    is not null;


-- ------------------------------------------------------------
-- SSLCOMMERZ risk level.
--
-- Current API:
-- 0 = safe
-- 1 = risky
--
-- Nullable until validation happens.
-- ------------------------------------------------------------

alter table public.payments
  add column if not exists
    risk_level smallint;


alter table public.payments
  add constraint
    payments_risk_level_check
  check (
    risk_level is null
    or risk_level in (0, 1)
  );


-- ============================================================
-- ACTIVE PAYMENT ATTEMPT PROTECTION
--
-- One order must not accidentally open multiple simultaneous
-- hosted-checkout sessions.
-- ============================================================

create unique index
  if not exists
    payments_one_active_attempt_per_order_idx
on public.payments (
  order_id
)
where status in (
  'CREATED',
  'REDIRECTED',
  'PENDING'
);


-- ============================================================
-- ATOMIC PAYMENT ATTEMPT CREATION
--
-- Browser never supplies:
-- - amount
-- - currency
-- - merchant transaction ID
-- - payment status
--
-- They come from the authoritative order/database.
-- ============================================================

create or replace function
  public.create_payment_attempt(
    p_order_id uuid,
    p_user_id uuid,
    p_provider text
  )
returns table (
  reused boolean,

  payment_id uuid,

  returned_order_id uuid,

  returned_provider text,

  merchant_transaction_id text,

  amount_bdt integer,

  currency text,

  status text,

  provider_session_id text,

  created_at timestamptz,

  updated_at timestamptz
)
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_order public.orders%rowtype;

  v_existing
    public.payments%rowtype;

  v_payment
    public.payments%rowtype;

  v_payment_id uuid;

  v_merchant_transaction_id text;

  v_lock_key bigint;
begin

  -- ----------------------------------------------------------
  -- Validate supported provider.
  --
  -- Actual production provider is locked to SSLCOMMERZ.
  -- ----------------------------------------------------------

  if p_provider <> 'SSLCOMMERZ' then
    raise exception
      'UNSUPPORTED_PAYMENT_PROVIDER';
  end if;


  -- ----------------------------------------------------------
  -- Serialize attempts for this order.
  -- ----------------------------------------------------------

  v_lock_key :=
    pg_catalog.hashtextextended(
      'PAYMENT|'
      || p_order_id::text,
      0
    );


  perform
    pg_catalog.pg_advisory_xact_lock(
      v_lock_key
    );


  -- ----------------------------------------------------------
  -- Load and lock authoritative order.
  -- ----------------------------------------------------------

  select o.*
  into v_order
  from public.orders as o
  where
    o.id = p_order_id
  for update;


  if not found then
    raise exception
      'ORDER_NOT_FOUND';
  end if;


  -- ----------------------------------------------------------
  -- Ownership protection.
  -- ----------------------------------------------------------

  if
    v_order.user_id <>
      p_user_id
  then
    raise exception
      'ORDER_OWNERSHIP_CONFLICT';
  end if;


  -- ----------------------------------------------------------
  -- Never create payment for terminal order.
  -- ----------------------------------------------------------

  if
    v_order.status in (
      'PAID',
      'CANCELLED',
      'EXPIRED',
      'REFUNDED'
    )
  then
    raise exception
      'ORDER_NOT_PAYABLE';
  end if;


  -- ----------------------------------------------------------
  -- Reuse an existing active payment attempt.
  -- ----------------------------------------------------------

  select p.*
  into v_existing
  from public.payments as p
  where
    p.order_id =
      p_order_id

    and p.provider =
      p_provider

    and p.status in (
      'CREATED',
      'REDIRECTED',
      'PENDING'
    )
  limit 1
  for update;


  if found then

    return query
    select
      true,
      p.id,
      p.order_id,
      p.provider,
      p.merchant_transaction_id,
      p.amount_bdt,
      p.currency,
      p.status,
      p.provider_session_id,
      p.created_at,
      p.updated_at
    from public.payments as p
    where
      p.id =
        v_existing.id;


    return;

  end if;


  -- ----------------------------------------------------------
  -- A new payment may only begin from CREATED order state.
  --
  -- PENDING_PAYMENT without an active payment would indicate
  -- inconsistent state and should not silently recover.
  -- ----------------------------------------------------------

  if
    v_order.status <>
      'CREATED'
  then
    raise exception
      'ORDER_NOT_READY_FOR_PAYMENT';
  end if;


  -- ----------------------------------------------------------
  -- Generate payment UUID first.
  -- ----------------------------------------------------------

  v_payment_id :=
    gen_random_uuid();


  -- ----------------------------------------------------------
  -- Generate <= 30-character merchant transaction ID.
  --
  -- Example:
  -- EM8F3E91A6...
  -- ----------------------------------------------------------

  v_merchant_transaction_id :=
    'EM'
    ||
    upper(
      substring(
        replace(
          v_payment_id::text,
          '-',
          ''
        )
        from 1
        for 28
      )
    );


  -- ----------------------------------------------------------
  -- Create payment attempt using order amount/currency.
  -- ----------------------------------------------------------

  insert into public.payments (
    id,
    order_id,
    provider,
    merchant_transaction_id,
    amount_bdt,
    currency,
    status
  )
  values (
    v_payment_id,
    v_order.id,
    p_provider,
    v_merchant_transaction_id,
    v_order.amount_bdt,
    v_order.currency,
    'CREATED'
  )
  returning *
  into v_payment;


  return query
  select
    false,
    v_payment.id,
    v_payment.order_id,
    v_payment.provider,
    v_payment.merchant_transaction_id,
    v_payment.amount_bdt,
    v_payment.currency,
    v_payment.status,
    v_payment.provider_session_id,
    v_payment.created_at,
    v_payment.updated_at;

end;
$$;


-- ============================================================
-- SECURITY
-- ============================================================

revoke all
on function public.create_payment_attempt(
  uuid,
  uuid,
  text
)
from
  public,
  anon,
  authenticated;


grant execute
on function public.create_payment_attempt(
  uuid,
  uuid,
  text
)
to service_role;


commit;